export interface Company {
  companyName: string;
  companyDescription: string;
  websiteUrl: string;
  industry: string;
  headquartersState: string;
  contactTitle: string;
  contactName: string;
  emailAddress: string;
  latestNews: string;
  founderName: string;
  founderEmail: string;
  linkedinUrl: string;
  emailDraft?: EmailContent;
}

export interface EmailContent {
  subject: string;
  body: string;
}

import { GoogleGenAI, Type } from "@google/genai";
import { Company, EmailContent } from '../types';

export const getSeriesALeads = async (icp: string): Promise<Company[]> => {
  if (!process.env.API_KEY) {
    throw new Error("API_KEY environment variable not set");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    You are a venture capital analyst specializing in early-stage startups. 
    Generate a list of exactly 100 realistic US-based companies that are 
    currently seeking or have recently obtained Series A funding. 

    ${icp ? `Crucially, prioritize companies that match the following Ideal Client Profile: "${icp}"` : 'Generate a diverse list of companies from various industries.'}

    **Strict Verification Constraints:**
    1. **Legal Registration**: You must verify that each company is a legally registered business in the United States. Do not include any company if you cannot verify its existence as a legal entity.
    2. **Website**: Ensure the websiteUrl provided is for an active, operating business and NOT a parked domain or a "domain for sale" page.

    Provide the information in a JSON array format. For each company, 
    include the following fields: 
    - companyName
    - companyDescription (a brief 1-2 sentence description)
    - websiteUrl
    - linkedinUrl (The LinkedIn profile URL for the contact person. If not available, use the company's LinkedIn page.)
    - industry
    - headquartersState
    - contactTitle
    - contactName
    - emailAddress (a plausible email for the contact person)
    - latestNews (a brief, 1-sentence update on recent company news)
    - founderName (The name of the company's founder)
    - founderEmail (The email address of the founder)

    **Contact Person Strategy:**
    1. **Primary Contact (Report to CEO)**: For 'contactName' and 'contactTitle', prioritize finding a specific, real person on LinkedIn who reports directly to the CEO (e.g., VP of Marketing, COO, Head of Product).
    2. **Founder Details (Deep Verification)**: Dig deep to identify the correct original Founder or Co-Founder. Do not assume the current CEO is the founder. Simulate a check of the company's "About Us" page and Articles of Incorporation to ensure you are listing the actual person who started the company.
    3. **Emails**: For both the primary contact and the founder, provide their email addresses based on LinkedIn profile data or company patterns. If a public email is available, use it. Otherwise, derive a high-confidence work email using the company's domain and standard email naming patterns (e.g. first.last@company.com).
  `;

  const responseSchema = {
    type: Type.ARRAY,
    items: {
      type: Type.OBJECT,
      properties: {
        companyName: {
          type: Type.STRING,
          description: "The name of the company.",
        },
        companyDescription: {
          type: Type.STRING,
          description: "A brief 1-2 sentence description of the company.",
        },
        websiteUrl: {
          type: Type.STRING,
          description: "The official website URL of the company.",
        },
        linkedinUrl: {
          type: Type.STRING,
          description: "The LinkedIn profile URL for the contact or company.",
        },
        industry: {
          type: Type.STRING,
          description: "The industry the company operates in.",
        },
        headquartersState: {
          type: Type.STRING,
          description: "The US state where the company is headquartered.",
        },
        contactTitle: {
          type: Type.STRING,
          description: "The job title of the primary contact person (e.g. VP, COO).",
        },
        contactName: {
          type: Type.STRING,
          description: "The full name of the primary contact person.",
        },
        emailAddress: {
          type: Type.STRING,
          description: "The email address of the primary contact person.",
        },
        latestNews: {
            type: Type.STRING,
            description: "A brief, 1-sentence update on recent company news.",
        },
        founderName: {
          type: Type.STRING,
          description: "The full name of the company Founder.",
        },
        founderEmail: {
          type: Type.STRING,
          description: "The email address of the company Founder.",
        },
      },
      required: ["companyName", "companyDescription", "websiteUrl", "linkedinUrl", "industry", "headquartersState", "contactTitle", "contactName", "emailAddress", "latestNews", "founderName", "founderEmail"],
    },
  };

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        temperature: 0.8,
      },
    });

    const jsonText = response.text.trim();
    const companies: Company[] = JSON.parse(jsonText);
    return companies.slice(0, 100);

  } catch (error) {
    console.error("Error generating leads from Gemini API:", error);
    throw new Error("Failed to generate company leads. Please check the console for more details.");
  }
};


export const generateEmailForCompany = async (company: Company): Promise<EmailContent> => {
    if (!process.env.API_KEY) {
        throw new Error("API_KEY environment variable not set");
    }

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const prompt = `
        You are a professional B2B copywriter for "Creative Blue", a high-end creative agency (https://www.creativeblue.agency/).

        Task: Draft a short, personalized lead magnet email to:
        Name: ${company.contactName}
        Title: ${company.contactTitle}
        Company: ${company.companyName}
        Description: ${company.companyDescription}
        Industry: ${company.industry}
        Location: ${company.headquartersState}
        Website: ${company.websiteUrl}
        Latest News: "${company.latestNews}"

        Guidelines:
        1.  **Subject Line**: Compelling, modern, and relevant to their news or industry.
        2.  **Opening**: Congratulate them on their latest news ("${company.latestNews}"). Be genuine.
        3.  **Value Proposition**: Seamlessly transition to how Creative Blue can support their growth. Recommend services from https://www.creativeblue.agency/services-overview (e.g., Brand Strategy, Web Design, Digital Marketing, Identity Design).
        4.  **Tone**: Professional, persuasive, and concise. Avoid overly promotional language ("salesy" jargon) or excessive exclamation points. Do NOT use threatening language (e.g., "you are losing money").
        5.  **Call to Action**: clear and polite, directing them to https://www.creativeblue.agency/contact.
        6.  **Sign-off**: Professional sign-off.

        Return the email as a JSON object with two keys: "subject" and "body". The body should use newline characters (\\n) for paragraph breaks.
    `;

    const responseSchema = {
        type: Type.OBJECT,
        properties: {
            subject: { type: Type.STRING },
            body: { type: Type.STRING }
        },
        required: ["subject", "body"],
    };

    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: responseSchema,
                temperature: 0.7,
            },
        });

        const jsonText = response.text.trim();
        const emailContent: EmailContent = JSON.parse(jsonText);
        return emailContent;

    } catch (error) {
        console.error("Error generating email from Gemini API:", error);
        throw new Error("Failed to draft email. Please try again.");
    }
};

import React, { useState, useCallback, useEffect } from 'react';
import { Company, EmailContent } from './types';
import { getSeriesALeads, generateEmailForCompany } from './services/geminiService';
import { exportToGoogleContacts, ensureGooglePermissions, filterExistingContacts, filterVerifiedLeads } from './services/googleContactsService';
import CompanyTable from './components/CompanyTable';
import LoadingSpinner from './components/LoadingSpinner';
import ErrorDisplay from './components/ErrorDisplay';
import InfoDisplay from './components/InfoDisplay';
import SuccessDisplay from './components/SuccessDisplay';
import EmailModal from './components/EmailModal';

const App: React.FC = () => {
  const [companies, setCompanies] = useState<Company[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [info, setInfo] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [isExportingContacts, setIsExportingContacts] = useState<boolean>(false);

  const defaultIcp = "Startup companies in the United States that have either obtained or are seeking Series A round of funding.";
  const [icp, setIcp] = useState<string>(defaultIcp);

  const [isDraftingEmailFor, setIsDraftingEmailFor] = useState<string | null>(null);

  // Selection state: Changed to use Company Name as ID since email can be empty
  const [selectedCompanyNames, setSelectedCompanyNames] = useState<Set<string>>(new Set());

  // State for the email modal as a fallback
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedCompany, setSelectedCompany] = useState<Company | null>(null);
  const [draftedEmail, setDraftedEmail] = useState<EmailContent | null>(null);

  // Email generation queue state
  const [emailGenProgress, setEmailGenProgress] = useState<{ current: number; total: number } | null>(null);


  const processEmailGeneration = useCallback(async (leadList: Company[]) => {
    let completed = 0;
    const total = leadList.length;
    setEmailGenProgress({ current: 0, total });

    // Process sequentially to be safe with rate limits, or small batches.
    // Given the prompt "generate for each company", we loop through all.
    for (const company of leadList) {
        // Skip if already has draft (unlikely for new list, but good practice)
        if (company.emailDraft) {
            completed++;
            setEmailGenProgress({ current: completed, total });
            continue;
        }

        try {
            const draft = await generateEmailForCompany(company);

            // Update state immediately for this company
            setCompanies(prevCompanies => 
                prevCompanies.map(c => 
                    c.companyName === company.companyName 
                        ? { ...c, emailDraft: draft } 
                        : c
                )
            );
        } catch (e) {
            console.warn(`Failed to auto-generate email for ${company.companyName}`, e);
        }

        completed++;
        setEmailGenProgress({ current: completed, total });
    }

    setEmailGenProgress(null);
  }, []);


  const fetchCompanies = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    setInfo(null);
    setSuccessMessage(null);
    setCompanies([]);
    setSelectedCompanyNames(new Set());
    setEmailGenProgress(null);

    try {
      // Attempt to get Google Contacts permission *before* the long generation process.
      await ensureGooglePermissions().catch(e => console.warn("Permissions check skipped:", e));

      const data = await getSeriesALeads(icp);

      // 1. Filter out companies that are already in Google Contacts
      const uniqueLeads = await filterExistingContacts(data);

      // 2. Verify leads (websites must work; invalid emails are cleared but lead kept)
      const verifiedLeads = await filterVerifiedLeads(uniqueLeads);

      const duplicateCount = data.length - uniqueLeads.length;
      const filteredByWebsite = uniqueLeads.length - verifiedLeads.length;

      if (data.length > 0 && (duplicateCount > 0 || filteredByWebsite > 0)) {
          let infoMsg = `Generated ${data.length} leads.`;
          if (duplicateCount > 0) infoMsg += ` Filtered ${duplicateCount} existing contacts.`;
          if (filteredByWebsite > 0) infoMsg += ` Removed ${filteredByWebsite} with invalid/for-sale websites.`;
          setInfo(infoMsg);
      }

      setCompanies(verifiedLeads);
      // Default: Select all valid leads
      setSelectedCompanyNames(new Set(verifiedLeads.map(c => c.companyName)));

      // Start background email generation
      if (verifiedLeads.length > 0) {
          processEmailGeneration(verifiedLeads);
      }

    } catch (err) {
      if (err instanceof Error) {
        setError(err.message);
      } else {
        setError('An unknown error occurred.');
      }
    } finally {
      setIsLoading(false);
    }
  }, [icp, processEmailGeneration]);

  const handleToggleSelection = useCallback((companyName: string) => {
    setSelectedCompanyNames(prev => {
      const newSet = new Set(prev);
      if (newSet.has(companyName)) {
        newSet.delete(companyName);
      } else {
        newSet.add(companyName);
      }
      return newSet;
    });
  }, []);

  const handleBulkSelection = useCallback((companyNames: string[], shouldSelect: boolean) => {
    setSelectedCompanyNames(prev => {
      const newSet = new Set(prev);
      companyNames.forEach(name => {
        if (shouldSelect) {
          newSet.add(name);
        } else {
          newSet.delete(name);
        }
      });
      return newSet;
    });
  }, []);

  const handleDraftEmail = useCallback(async (company: Company) => {
    setError(null);
    setInfo(null);
    setSuccessMessage(null);

    // If draft already exists, just open it
    if (company.emailDraft) {
        const { subject, body } = company.emailDraft;
        const gmailUrl = `https://mail.google.com/mail/?view=cm&fs=1&to=${encodeURIComponent(company.emailAddress)}&su=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;

        const newWindow = window.open(gmailUrl, '_blank', 'noopener,noreferrer');

        if (!newWindow || newWindow.closed || typeof newWindow.closed === 'undefined') {
            setInfo("Pop-up blocked. Opening draft details below.");
            setSelectedCompany(company);
            setDraftedEmail(company.emailDraft);
            setIsModalOpen(true);
        }
        return;
    }

    if (!company.emailAddress) {
        setError(`Cannot draft email for ${company.companyName}: No email address available.`);
        return;
    }

    setIsDraftingEmailFor(company.companyName);

    try {
        const emailContent = await generateEmailForCompany(company);

        // Save the draft to the company state so we don't regenerate
        setCompanies(prev => prev.map(c => c.companyName === company.companyName ? { ...c, emailDraft: emailContent } : c));

        const subject = encodeURIComponent(emailContent.subject);
        const body = encodeURIComponent(emailContent.body);

        const gmailUrl = `https://mail.google.com/mail/?view=cm&fs=1&to=${encodeURIComponent(company.emailAddress)}&su=${subject}&body=${body}`;

        const newWindow = window.open(gmailUrl, '_blank', 'noopener,noreferrer');

        if (!newWindow || newWindow.closed || typeof newWindow.closed === 'undefined') {
          // Pop-up was blocked
          setInfo("Your browser's pop-up blocker prevented Gmail from opening. We've opened the draft in a modal below. To open Gmail directly next time, please allow pop-ups for this site.");
          setSelectedCompany(company);
          setDraftedEmail(emailContent);
          setIsModalOpen(true);
        }
    } catch (err) {
        const errorMessage = err instanceof Error ? err.message : 'An unknown error occurred while drafting the email.';
        setError(`Could not draft email for ${company.companyName}. Reason: ${errorMessage}`);
    } finally {
        setIsDraftingEmailFor(null);
    }
  }, []);

  const handleAddToContacts = useCallback(async () => {
    const companiesToExport = companies.filter(c => selectedCompanyNames.has(c.companyName));

    if (companiesToExport.length === 0) {
        setInfo("No companies selected to export.");
        return;
    }

    setIsExportingContacts(true);
    setError(null);
    setSuccessMessage(null);
    try {
        const result = await exportToGoogleContacts(companiesToExport);
        setSuccessMessage(result);
    } catch (err: any) {
        console.error("Full export error:", err);
        let msg = "Failed to export contacts.";

        if (err.message) {
            msg += ` ${err.message}`;
        } else if (err.result && err.result.error && err.result.error.message) {
            msg += ` ${err.result.error.message}`;
        } else if (err.error && err.error.message) {
            msg += ` ${err.error.message}`;
        } else {
             // Try to stringify if it's a weird object
            try {
                msg += ` ${JSON.stringify(err)}`;
            } catch (e) {
                msg += " Unknown error object.";
            }
        }

        if (msg.includes("GOOGLE_CLIENT_ID")) {
           msg = "Configuration Error: GOOGLE_CLIENT_ID is missing. Please check your environment settings.";
        }
        setError(msg);
    } finally {
        setIsExportingContacts(false);
    }
  }, [companies, selectedCompanyNames]);


  return (
    <>
    <div className="min-h-screen bg-gray-900 text-white font-sans flex flex-col items-center p-4 sm:p-6 md:p-8">
      <div className="w-full max-w-7xl mx-auto">
        <header className="text-center mb-8">
          <h1 className="text-4xl sm:text-5xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-blue-600">
            Creative Blue Lead Generator
          </h1>
          <p className="mt-2 text-lg text-gray-400">
            Generate targeted leads and draft outreach emails with AI.
          </p>
        </header>

        <main className="flex flex-col items-center">
          <div className="w-full max-w-2xl bg-gray-800/50 p-6 rounded-lg border border-gray-700 mb-8">
             <label htmlFor="icp" className="block text-sm font-medium text-gray-300 mb-2">
                Ideal Client Profile
            </label>
            <textarea
                id="icp"
                value={icp}
                onChange={(e) => setIcp(e.target.value)}
                placeholder="e.g., B2B SaaS companies in the fintech space with over $1M in ARR..."
                className="w-full h-24 p-3 bg-gray-900 border border-gray-600 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-colors text-gray-200 placeholder-gray-500"
            />
            <p className="mt-2 text-xs text-gray-500">Describe the type of companies you're looking for to get more targeted results.</p>
          </div>

          <div className="w-full flex flex-col sm:flex-row justify-center gap-4 mb-8">
            <button
              onClick={fetchCompanies}
              disabled={isLoading || (emailGenProgress !== null)}
              className="px-8 py-3 bg-blue-600 text-white font-bold rounded-lg shadow-lg hover:bg-blue-700 disabled:bg-blue-900 disabled:cursor-not-allowed disabled:text-gray-400 transition-all duration-300 ease-in-out transform hover:scale-105 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-opacity-50"
            >
              {isLoading ? 'Finding Companies...' : (emailGenProgress ? `Drafting Emails (${emailGenProgress.current}/${emailGenProgress.total})...` : 'Generate New Leads')}
            </button>
            {companies.length > 0 && (
                <button
                    onClick={handleAddToContacts}
                    disabled={isExportingContacts || selectedCompanyNames.size === 0}
                    className="px-8 py-3 bg-green-600 text-white font-bold rounded-lg shadow-lg hover:bg-green-700 disabled:bg-green-900 disabled:cursor-not-allowed disabled:text-gray-400 transition-all duration-300 ease-in-out transform hover:scale-105 focus:outline-none focus:ring-2 focus:ring-green-500 focus:ring-opacity-50"
                >
                    {isExportingContacts 
                      ? 'Adding...' 
                      : selectedCompanyNames.size > 0 
                        ? `Add ${selectedCompanyNames.size} Selected to Contacts` 
                        : 'Select Leads to Add'}
                </button>
            )}
          </div>

          <div className="w-full">
            {isLoading && <LoadingSpinner />}
            {emailGenProgress && (
                <div className="mb-4 w-full bg-gray-800 rounded-full h-2.5 dark:bg-gray-700 overflow-hidden">
                    <div className="bg-blue-600 h-2.5 rounded-full transition-all duration-500" style={{ width: `${(emailGenProgress.current / emailGenProgress.total) * 100}%` }}></div>
                    <p className="text-center text-xs text-gray-400 mt-1">Automatically generating email drafts: {emailGenProgress.current} / {emailGenProgress.total}</p>
                </div>
            )}
            {error && <ErrorDisplay message={error} />}
            {info && <InfoDisplay message={info} />}
            {successMessage && <SuccessDisplay message={successMessage} />}
            {companies.length > 0 && !isLoading && (
              <CompanyTable 
                companies={companies} 
                onDraftEmail={handleDraftEmail}
                isDraftingEmailFor={isDraftingEmailFor}
                selectedCompanyNames={selectedCompanyNames}
                onToggleSelection={handleToggleSelection}
                onBulkSelection={handleBulkSelection}
              />
            )}
            {!isLoading && !error && companies.length === 0 && (
                 <div className="text-center p-8 bg-gray-800/50 rounded-lg border border-gray-700">
                    <p className="text-gray-400">Refine your profile above and click the button to generate your first list of company leads.</p>
                </div>
            )}
          </div>
        </main>
      </div>
    </div>
    <EmailModal
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        company={selectedCompany}
        emailContent={draftedEmail}
        isLoading={false}
        error={null}
    />
    </>
  );
};

export default App;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Company } from '../types';

interface CompanyTableProps {
  companies: Company[];
  onDraftEmail: (company: Company) => void;
  isDraftingEmailFor: string | null;
  selectedCompanyNames: Set<string>;
  onToggleSelection: (companyName: string) => void;
  onBulkSelection: (companyNames: string[], shouldSelect: boolean) => void;
}

const CompanyTable: React.FC<CompanyTableProps> = ({ 
  companies, 
  onDraftEmail, 
  isDraftingEmailFor,
  selectedCompanyNames,
  onToggleSelection,
  onBulkSelection
}) => {
  const [founderFilter, setFounderFilter] = useState('');
  const [industryFilter, setIndustryFilter] = useState('');
  const [stateFilter, setStateFilter] = useState('');
  const headerCheckboxRef = useRef<HTMLInputElement>(null);

  const headers = [
    'Select',
    'Company Name',
    'Description',
    'Latest News',
    'Website',
    'LinkedIn',
    'Industry',
    'Headquarters State',
    'Contact Title',
    'Contact Name',
    'Email Address',
    'Founder Name',
    'Founder Email',
    'Actions',
  ];

  // Helper function to ensure URL has protocol
  const getSafeUrl = (url: string) => {
    if (!url) return '#';
    const trimmedUrl = url.trim();
    if (trimmedUrl.startsWith('http://') || trimmedUrl.startsWith('https://')) {
      return trimmedUrl;
    }
    return `https://${trimmedUrl}`;
  };

  const isValidUrl = (url: string) => {
      if (!url) return false;
      const lower = url.toLowerCase().trim();
      return lower.length > 0 && !['n/a', 'none', 'unavailable', 'not found', 'null', '-'].includes(lower);
  };

  // Extract unique values for dropdowns
  const uniqueIndustries = useMemo(() => {
    const industries = new Set(companies.map(c => c.industry).filter(Boolean));
    return Array.from(industries).sort();
  }, [companies]);

  const uniqueStates = useMemo(() => {
    const states = new Set(companies.map(c => c.headquartersState).filter(Boolean));
    return Array.from(states).sort();
  }, [companies]);

  // Filter logic
  const filteredCompanies = useMemo(() => {
    return companies.filter(company => {
      const matchesFounder = company.founderName.toLowerCase().includes(founderFilter.toLowerCase());
      const matchesIndustry = industryFilter === '' || company.industry === industryFilter;
      const matchesState = stateFilter === '' || company.headquartersState === stateFilter;

      return matchesFounder && matchesIndustry && matchesState;
    });
  }, [companies, founderFilter, industryFilter, stateFilter]);

  // Selection logic
  const allFilteredSelected = filteredCompanies.length > 0 && filteredCompanies.every(c => selectedCompanyNames.has(c.companyName));
  const isIndeterminate = filteredCompanies.some(c => selectedCompanyNames.has(c.companyName)) && !allFilteredSelected;

  useEffect(() => {
    if (headerCheckboxRef.current) {
      headerCheckboxRef.current.indeterminate = isIndeterminate;
    }
  }, [isIndeterminate]);

  const handleHeaderCheckboxChange = () => {
    const names = filteredCompanies.map(c => c.companyName);
    // If all currently filtered are selected, unselect them. Otherwise, select them all.
    onBulkSelection(names, !allFilteredSelected);
  };

  return (
    <div className="w-full flex flex-col gap-4">
      {/* Filter Controls */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 bg-gray-800 p-4 rounded-lg border border-gray-700 shadow-sm">
        <div className="flex flex-col">
          <label htmlFor="founderFilter" className="text-xs font-semibold text-gray-400 uppercase mb-1">Filter by Founder</label>
          <input
            id="founderFilter"
            type="text"
            placeholder="Search founder name..."
            value={founderFilter}
            onChange={(e) => setFounderFilter(e.target.value)}
            className="bg-gray-900 border border-gray-600 text-white text-sm rounded-md focus:ring-blue-500 focus:border-blue-500 block w-full p-2.5 placeholder-gray-500"
          />
        </div>

        <div className="flex flex-col">
          <label htmlFor="industryFilter" className="text-xs font-semibold text-gray-400 uppercase mb-1">Filter by Industry</label>
          <select
            id="industryFilter"
            value={industryFilter}
            onChange={(e) => setIndustryFilter(e.target.value)}
            className="bg-gray-900 border border-gray-600 text-white text-sm rounded-md focus:ring-blue-500 focus:border-blue-500 block w-full p-2.5"
          >
            <option value="">All Industries</option>
            {uniqueIndustries.map((ind) => (
              <option key={ind} value={ind}>{ind}</option>
            ))}
          </select>
        </div>

        <div className="flex flex-col">
          <label htmlFor="stateFilter" className="text-xs font-semibold text-gray-400 uppercase mb-1">Filter by State</label>
          <select
            id="stateFilter"
            value={stateFilter}
            onChange={(e) => setStateFilter(e.target.value)}
            className="bg-gray-900 border border-gray-600 text-white text-sm rounded-md focus:ring-blue-500 focus:border-blue-500 block w-full p-2.5"
          >
            <option value="">All States</option>
            {uniqueStates.map((st) => (
              <option key={st} value={st}>{st}</option>
            ))}
          </select>
        </div>
      </div>

      {/* Table */}
      <div className="w-full overflow-hidden rounded-lg shadow-lg border border-gray-700">
        <div className="overflow-x-auto">
          <table className="min-w-full leading-normal bg-gray-800 text-white">
            <thead>
              <tr>
                <th className="px-5 py-3 border-b-2 border-gray-600 bg-gray-700 text-left">
                  <input
                    type="checkbox"
                    ref={headerCheckboxRef}
                    checked={allFilteredSelected}
                    onChange={handleHeaderCheckboxChange}
                    className="w-4 h-4 text-blue-600 bg-gray-700 border-gray-600 rounded focus:ring-blue-600 ring-offset-gray-800 focus:ring-2"
                    disabled={filteredCompanies.length === 0}
                  />
                </th>
                {headers.slice(1).map((header) => (
                  <th
                    key={header}
                    className="px-5 py-3 border-b-2 border-gray-600 bg-gray-700 text-left text-xs font-semibold uppercase tracking-wider whitespace-nowrap"
                  >
                    {header}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {filteredCompanies.length > 0 ? (
                filteredCompanies.map((company, index) => {
                  const isSelected = selectedCompanyNames.has(company.companyName);
                  const isDrafting = isDraftingEmailFor === company.companyName;
                  const hasDraft = !!company.emailDraft;

                  return (
                    <tr key={index} className={`border-b border-gray-700 hover:bg-gray-700 ${isSelected ? 'bg-gray-700/50' : ''}`}>
                      <td className="px-5 py-4 text-sm">
                        <input
                          type="checkbox"
                          checked={isSelected}
                          onChange={() => onToggleSelection(company.companyName)}
                          className="w-4 h-4 text-blue-600 bg-gray-700 border-gray-600 rounded focus:ring-blue-600 ring-offset-gray-800 focus:ring-2"
                        />
                      </td>
                      <td className="px-5 py-4 text-sm">
                        <p className="whitespace-no-wrap font-semibold">{company.companyName}</p>
                      </td>
                      <td className="px-5 py-4 text-sm min-w-[200px]">
                        <p className="text-gray-300 whitespace-normal">{company.companyDescription}</p>
                      </td>
                      <td className="px-5 py-4 text-sm min-w-[200px]">
                        <p className="text-gray-300 whitespace-normal">{company.latestNews}</p>
                      </td>
                      <td className="px-5 py-4 text-sm">
                        {isValidUrl(company.websiteUrl) ? (
                            <a 
                              href={getSafeUrl(company.websiteUrl)} 
                              target="_blank" 
                              rel="noopener noreferrer" 
                              className="text-blue-400 hover:text-blue-300 whitespace-no-wrap"
                            >
                              {company.websiteUrl}
                            </a>
                        ) : (
                            <span className="text-gray-500">-</span>
                        )}
                      </td>
                      <td className="px-5 py-4 text-sm">
                        {isValidUrl(company.linkedinUrl) ? (
                          <div className="max-w-[200px] truncate" title={company.linkedinUrl}>
                            <a 
                              href={getSafeUrl(company.linkedinUrl)} 
                              target="_blank" 
                              rel="noopener noreferrer" 
                              className="text-blue-400 hover:text-blue-300"
                            >
                              {company.linkedinUrl}
                            </a>
                          </div>
                        ) : (
                          <span className="text-gray-500">-</span>
                        )}
                      </td>
                      <td className="px-5 py-4 text-sm">
                        <p className="whitespace-no-wrap text-gray-300">{company.industry}</p>
                      </td>
                      <td className="px-5 py-4 text-sm">
                        <p className="whitespace-no-wrap text-gray-300">{company.headquartersState}</p>
                      </td>
                      <td className="px-5 py-4 text-sm">
                        <p className="whitespace-no-wrap text-gray-300">{company.contactTitle}</p>
                      </td>
                      <td className="px-5 py-4 text-sm">
                        <p className="whitespace-no-wrap text-gray-300">{company.contactName}</p>
                      </td>
                      <td className="px-5 py-4 text-sm">
                        {company.emailAddress ? (
                          <a href={`mailto:${company.emailAddress}`} className="text-blue-400 hover:text-blue-300 whitespace-no-wrap">
                            {company.emailAddress}
                          </a>
                        ) : (
                            <span className="text-gray-500 italic text-xs">Unverified/Empty</span>
                        )}
                      </td>
                      <td className="px-5 py-4 text-sm">
                        <p className="whitespace-no-wrap text-gray-300">{company.founderName}</p>
                      </td>
                      <td className="px-5 py-4 text-sm">
                         {company.founderEmail ? (
                            <a href={`mailto:${company.founderEmail}`} className="text-blue-400 hover:text-blue-300 whitespace-no-wrap">
                              {company.founderEmail}
                            </a>
                         ) : (
                            <span className="text-gray-500 italic text-xs">Unverified/Empty</span>
                         )}
                      </td>
                      <td className="px-5 py-4 text-sm">
                          <button
                              onClick={() => onDraftEmail(company)}
                              disabled={isDrafting || (!company.emailAddress && !hasDraft)}
                              className={`px-4 py-2 text-xs font-semibold text-white rounded-md transition-colors whitespace-nowrap ${
                                hasDraft 
                                  ? 'bg-emerald-600 hover:bg-emerald-700' 
                                  : 'bg-blue-600 hover:bg-blue-700'
                              } disabled:bg-gray-700 disabled:text-gray-500 disabled:cursor-not-allowed`}
                          >
                              {isDrafting ? 'Drafting...' : hasDraft ? 'View Draft' : 'Draft Email'}
                          </button>
                      </td>
                    </tr>
                  );
                })
              ) : (
                <tr>
                  <td colSpan={headers.length} className="px-5 py-8 text-center text-gray-400">
                    No companies match the selected filters.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default CompanyTable;

import React, { useState, useCallback, useEffect } from 'react';
import { Company, EmailContent } from './types';
import { getSeriesALeads, generateEmailForCompany } from './services/geminiService';
import { exportToGoogleContacts, filterExistingContacts, filterVerifiedLeads } from './services/googleContactsService';
import CompanyTable from './components/CompanyTable';
import LoadingSpinner from './components/LoadingSpinner';
import ErrorDisplay from './components/ErrorDisplay';
import InfoDisplay from './components/InfoDisplay';
import SuccessDisplay from './components/SuccessDisplay';
import EmailModal from './components/EmailModal';

const App: React.FC = () => {
  const [companies, setCompanies] = useState<Company[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [info, setInfo] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [isExportingContacts, setIsExportingContacts] = useState<boolean>(false);

  const defaultIcp = "Startup companies in the United States that have either obtained or are seeking Series A round of funding.";
  const [icp, setIcp] = useState<string>(defaultIcp);

  const [isDraftingEmailFor, setIsDraftingEmailFor] = useState<string | null>(null);

  // Selection state: Changed to use Company Name as ID since email can be empty
  const [selectedCompanyNames, setSelectedCompanyNames] = useState<Set<string>>(new Set());

  // State for the email modal as a fallback
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedCompany, setSelectedCompany] = useState<Company | null>(null);
  const [draftedEmail, setDraftedEmail] = useState<EmailContent | null>(null);

  // Email generation queue state
  const [emailGenProgress, setEmailGenProgress] = useState<{ current: number; total: number } | null>(null);


  const processEmailGeneration = useCallback(async (leadList: Company[]) => {
    let completed = 0;
    const total = leadList.length;
    setEmailGenProgress({ current: 0, total });

    // Process sequentially to be safe with rate limits, or small batches.
    // Given the prompt "generate for each company", we loop through all.
    for (const company of leadList) {
        // Skip if already has draft (unlikely for new list, but good practice)
        if (company.emailDraft) {
            completed++;
            setEmailGenProgress({ current: completed, total });
            continue;
        }

        try {
            const draft = await generateEmailForCompany(company);

            // Update state immediately for this company
            setCompanies(prevCompanies => 
                prevCompanies.map(c => 
                    c.companyName === company.companyName 
                        ? { ...c, emailDraft: draft } 
                        : c
                )
            );
        } catch (e) {
            console.warn(`Failed to auto-generate email for ${company.companyName}`, e);
        }

        completed++;
        setEmailGenProgress({ current: completed, total });
    }

    setEmailGenProgress(null);
  }, []);


  const fetchCompanies = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    setInfo(null);
    setSuccessMessage(null);
    setCompanies([]);
    setSelectedCompanyNames(new Set());
    setEmailGenProgress(null);

    try {
      // NOTE: Removed automatic ensureGooglePermissions() to avoid blocking "redirect_uri_mismatch" errors 
      // for users who haven't configured their Google Cloud Console correctly.
      // Permissions will be requested only when clicking "Add to Contacts".

      const data = await getSeriesALeads(icp);

      // 1. Filter out companies that are already in Google Contacts (will skip if no auth)
      const uniqueLeads = await filterExistingContacts(data);

      // 2. Verify leads (websites must work; invalid emails are cleared but lead kept)
      const verifiedLeads = await filterVerifiedLeads(uniqueLeads);

      const duplicateCount = data.length - uniqueLeads.length;
      const filteredByWebsite = uniqueLeads.length - verifiedLeads.length;

      if (data.length > 0 && (duplicateCount > 0 || filteredByWebsite > 0)) {
          let infoMsg = `Generated ${data.length} leads.`;
          if (duplicateCount > 0) infoMsg += ` Filtered ${duplicateCount} existing contacts.`;
          if (filteredByWebsite > 0) infoMsg += ` Removed ${filteredByWebsite} with invalid/for-sale websites or unverified emails.`;
          setInfo(infoMsg);
      }

      setCompanies(verifiedLeads);
      // Default: Select all valid leads
      setSelectedCompanyNames(new Set(verifiedLeads.map(c => c.companyName)));

      // Start background email generation
      if (verifiedLeads.length > 0) {
          processEmailGeneration(verifiedLeads);
      }

    } catch (err) {
      if (err instanceof Error) {
        setError(err.message);
      } else {
        setError('An unknown error occurred.');
      }
    } finally {
      setIsLoading(false);
    }
  }, [icp, processEmailGeneration]);

  const handleToggleSelection = useCallback((companyName: string) => {
    setSelectedCompanyNames(prev => {
      const newSet = new Set(prev);
      if (newSet.has(companyName)) {
        newSet.delete(companyName);
      } else {
        newSet.add(companyName);
      }
      return newSet;
    });
  }, []);

  const handleBulkSelection = useCallback((companyNames: string[], shouldSelect: boolean) => {
    setSelectedCompanyNames(prev => {
      const newSet = new Set(prev);
      companyNames.forEach(name => {
        if (shouldSelect) {
          newSet.add(name);
        } else {
          newSet.delete(name);
        }
      });
      return newSet;
    });
  }, []);

  const handleDraftEmail = useCallback(async (company: Company) => {
    setError(null);
    setInfo(null);
    setSuccessMessage(null);

    // If draft already exists, just open it
    if (company.emailDraft) {
        const { subject, body } = company.emailDraft;
        const gmailUrl = `https://mail.google.com/mail/?view=cm&fs=1&to=${encodeURIComponent(company.emailAddress)}&su=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;

        const newWindow = window.open(gmailUrl, '_blank', 'noopener,noreferrer');

        if (!newWindow || newWindow.closed || typeof newWindow.closed === 'undefined') {
            setInfo("Pop-up blocked. Opening draft details below.");
            setSelectedCompany(company);
            setDraftedEmail(company.emailDraft);
            setIsModalOpen(true);
        }
        return;
    }

    if (!company.emailAddress) {
        setError(`Cannot draft email for ${company.companyName}: No email address available.`);
        return;
    }

    setIsDraftingEmailFor(company.companyName);

    try {
        const emailContent = await generateEmailForCompany(company);

        // Save the draft to the company state so we don't regenerate
        setCompanies(prev => prev.map(c => c.companyName === company.companyName ? { ...c, emailDraft: emailContent } : c));

        const subject = encodeURIComponent(emailContent.subject);
        const body = encodeURIComponent(emailContent.body);

        const gmailUrl = `https://mail.google.com/mail/?view=cm&fs=1&to=${encodeURIComponent(company.emailAddress)}&su=${subject}&body=${body}`;

        const newWindow = window.open(gmailUrl, '_blank', 'noopener,noreferrer');

        if (!newWindow || newWindow.closed || typeof newWindow.closed === 'undefined') {
          // Pop-up was blocked
          setInfo("Your browser's pop-up blocker prevented Gmail from opening. We've opened the draft in a modal below. To open Gmail directly next time, please allow pop-ups for this site.");
          setSelectedCompany(company);
          setDraftedEmail(emailContent);
          setIsModalOpen(true);
        }
    } catch (err) {
        const errorMessage = err instanceof Error ? err.message : 'An unknown error occurred while drafting the email.';
        setError(`Could not draft email for ${company.companyName}. Reason: ${errorMessage}`);
    } finally {
        setIsDraftingEmailFor(null);
    }
  }, []);

  const handleAddToContacts = useCallback(async () => {
    const companiesToExport = companies.filter(c => selectedCompanyNames.has(c.companyName));

    if (companiesToExport.length === 0) {
        setInfo("No companies selected to export.");
        return;
    }

    setIsExportingContacts(true);
    setError(null);
    setSuccessMessage(null);
    try {
        const result = await exportToGoogleContacts(companiesToExport);
        setSuccessMessage(result);
    } catch (err: any) {
        console.error("Full export error:", err);
        let msg = "Failed to export contacts.";

        if (err.message) {
            msg += ` ${err.message}`;
        } else if (err.result && err.result.error && err.result.error.message) {
            msg += ` ${err.result.error.message}`;
        } else if (err.error && err.error.message) {
            msg += ` ${err.error.message}`;
        } else {
             // Try to stringify if it's a weird object
            try {
                msg += ` ${JSON.stringify(err)}`;
            } catch (e) {
                msg += " Unknown error object.";
            }
        }

        if (msg.includes("redirect_uri_mismatch") || msg.includes("origin_mismatch")) {
            msg = "Access Blocked: The application is running on an unauthorized domain (e.g. preview environment). Google Contacts export is only available on authorized domains.";
        }
        else if (msg.includes("GOOGLE_CLIENT_ID")) {
           msg = "Configuration Error: GOOGLE_CLIENT_ID is missing or invalid. Please check your environment settings.";
        }
        setError(msg);
    } finally {
        setIsExportingContacts(false);
    }
  }, [companies, selectedCompanyNames]);


  return (
    <>
    <div className="min-h-screen bg-gray-900 text-white font-sans flex flex-col items-center p-4 sm:p-6 md:p-8">
      <div className="w-full max-w-7xl mx-auto">
        <header className="text-center mb-8">
          <h1 className="text-4xl sm:text-5xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-blue-600">
            Creative Blue Lead Generator
          </h1>
          <p className="mt-2 text-lg text-gray-400">
            Generate targeted leads and draft outreach emails with AI.
          </p>
        </header>

        <main className="flex flex-col items-center">
          <div className="w-full max-w-2xl bg-gray-800/50 p-6 rounded-lg border border-gray-700 mb-8">
             <label htmlFor="icp" className="block text-sm font-medium text-gray-300 mb-2">
                Ideal Client Profile
            </label>
            <textarea
                id="icp"
                value={icp}
                onChange={(e) => setIcp(e.target.value)}
                placeholder="e.g., B2B SaaS companies in the fintech space with over $1M in ARR..."
