export const getSeriesALeads = async (icp: string): Promise<Company[]> => {
  if (!process.env.API_KEY) {
    throw new Error("API_KEY environment variable not set");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Persona: Expert Market Researcher
  const prompt = `
    You are an expert market researcher and query formulation specialist. Your task is to perform an in-depth research simulation to find potential companies matching the following Ideal Client Profile:
    "${icp || 'Companies seeking or obtained Series A funding'}"

    **Research Strategy:**
    1.  **Query Formulation**: Internally formulate precise search queries to find companies matching the profile.
    2.  **In-Depth Search Simulation**: Simulate a deep web search to identify exactly 20 potential companies.
    3.  **Data Gathering**: For each company, gather:
        -   **Company Name**
        -   **Description**
        -   **Latest News**: A brief summary of good news from the past few months. If available, prioritize a recent LinkedIn post or press release.
        -   **Website**: Must be functional.
        -   **LinkedIn**: Must be functional.
        -   **Industry**
        -   **Headquarters State**
        -   **Contact Person**: Prioritize Head of Operations, COO, Head of Marketing, CMO, or someone reporting to the founder.
        -   **Contact Email**: A plausible, high-confidence work email (e.g., FirstName@WebsiteDomain).
        -   **Founder**: The name and email of the original founder.

    **Strict Constraints:**
    -   Exclude companies that do not have a plausible Website or LinkedIn page.
    -   Exclude companies where you cannot confidently derive a Contact Email or Founder Email.
    -   Ensure the "Latest News" is relevant and recent.

    Provide the results in a JSON array.
  `;

  const responseSchema = {
    type: Type.ARRAY,
    items: {
      type: Type.OBJECT,
      properties: {
        companyName: {
          type: Type.STRING,
          description: "The name of the company.",
        },
        companyDescription: {
          type: Type.STRING,
          description: "A brief description of the company.",
        },
        websiteUrl: {
          type: Type.STRING,
          description: "The official website URL.",
        },
