import { Company } from '../types';

const SCOPES = 'https://www.googleapis.com/auth/spreadsheets';
const DISCOVERY_DOC = 'https://sheets.googleapis.com/$discovery/rest?version=v4';

// Types for global google objects
declare global {
  interface Window {
    gapi: any;
    google: any;
  }
}

let tokenClient: any;
let gapiInited = false;
let gisInited = false;

export const initializeGapiClient = async () => {
  if (gapiInited) return;

  await new Promise<void>((resolve, reject) => {
    window.gapi.load('client', { callback: resolve, onerror: reject });
  });

  await window.gapi.client.init({
    discoveryDocs: [DISCOVERY_DOC],
  });

  gapiInited = true;
};

export const initializeGoogleIdentityClient = (clientId: string) => {
    if (gisInited && tokenClient) return tokenClient;

    tokenClient = window.google.accounts.oauth2.initTokenClient({
        client_id: clientId,
        scope: SCOPES,
        callback: '', // defined at request time
    });

    gisInited = true;
    return tokenClient;
};

const getSheetTitleFromGid = async (spreadsheetId: string, gid: number): Promise<string> => {
    const response = await window.gapi.client.sheets.spreadsheets.get({
        spreadsheetId: spreadsheetId,
        fields: 'sheets.properties',
    });

    const sheets = response.result.sheets;
    const sheet = sheets.find((s: any) => s.properties.sheetId === gid);

    return sheet ? sheet.properties.title : '';
};

const extractSpreadsheetDetails = (url: string) => {
    const regex = /\/d\/([a-zA-Z0-9-_]+)/;
    const match = url.match(regex);
    const spreadsheetId = match ? match[1] : null;

    let gid = 0;
    const gidMatch = url.match(/[#&?]gid=(\d+)/);
    if (gidMatch) {
        gid = parseInt(gidMatch[1], 10);
    }

    return { spreadsheetId, gid };
};

export const exportToGoogleSheets = async (
    companies: Company[], 
    sheetUrl: string, 
    clientId: string
): Promise<void> => {
    if (!companies || companies.length === 0) throw new Error("No data to export");
    if (!sheetUrl) throw new Error("Sheet URL is missing");
    if (!clientId) throw new Error("Google Client ID is missing");

    // 1. Ensure libraries are loaded
    await initializeGapiClient();
    initializeGoogleIdentityClient(clientId);

    // 2. Request Access Token
    await new Promise<void>((resolve, reject) => {
        tokenClient.callback = (resp: any) => {
            if (resp.error) {
                reject(resp);
            }
            resolve();
        };
        // Request token (prompt user if needed, or silent if already signed in)
        tokenClient.requestAccessToken({ prompt: '' });
    });

    // 3. Parse URL
    const { spreadsheetId, gid } = extractSpreadsheetDetails(sheetUrl);
    if (!spreadsheetId) throw new Error("Invalid Google Sheet URL");

    // 4. Get Sheet Name (Tab Name)
    let range = 'A1';
    try {
        const sheetTitle = await getSheetTitleFromGid(spreadsheetId, gid);
        if (sheetTitle) {
            // Quote the title if it contains spaces
            range = `'${sheetTitle}'!A1`;
        }
    } catch (e) {
        console.warn("Could not fetch sheet metadata, defaulting to first sheet append.", e);
    }

    // 5. Format Data
    const values = companies.map(c => [
        c.companyName,
        c.companyDescription,
        c.websiteUrl,
        c.industry,
        c.headquartersState,
        c.contactName,
        c.contactTitle,
        c.emailAddress,
        c.founderName,
        c.founderEmail,
        c.latestNews,
        c.linkedinUrl,
        c.emailDraft?.subject || '',
        c.emailDraft?.body || ''
    ]);

    // 6. Append Data
    const body = {
        values: values,
    };

    await window.gapi.client.sheets.spreadsheets.values.append({
        spreadsheetId: spreadsheetId,
        range: range,
        valueInputOption: 'USER_ENTERED',
        resource: body,
    });
};

import React, { useState, useCallback, useEffect } from 'react';
import { Company, EmailContent } from './types';
import { getSeriesALeads, generateEmailForCompany } from './services/geminiService';
import { filterVerifiedLeads } from './services/verificationService';
import { exportToGoogleSheets } from './services/sheetsService';
import CompanyTable from './components/CompanyTable';
import LoadingSpinner from './components/LoadingSpinner';
import ErrorDisplay from './components/ErrorDisplay';
import InfoDisplay from './components/InfoDisplay';
import SuccessDisplay from './components/SuccessDisplay';
import EmailModal from './components/EmailModal';

// Constants
const DEFAULT_SHEET_URL = "https://docs.google.com/spreadsheets/d/1f4Y9M89GssWIxTbBUxP557_ruWnCG4PIV-f3Slo5CG0/edit?gid=516299967#gid=516299967";

const App: React.FC = () => {
  const [companies, setCompanies] = useState<Company[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [info, setInfo] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  const defaultIcp = "Startup companies in the United States that have either obtained or are seeking Series A round of funding.";
  const [icp, setIcp] = useState<string>(defaultIcp);

  // Selection state
  const [selectedCompanyNames, setSelectedCompanyNames] = useState<Set<string>>(new Set());

  // Email generation queue state
  const [emailGenProgress, setEmailGenProgress] = useState<{ current: number; total: number } | null>(null);

  // Sheets Config
  const [sheetUrl, setSheetUrl] = useState<string>(DEFAULT_SHEET_URL);
  const [clientId, setClientId] = useState<string>('');
  const [showConfig, setShowConfig] = useState<boolean>(false);
  const [isExporting, setIsExporting] = useState<boolean>(false);

  useEffect(() => {
    // Load persisted config
    const savedClientId = localStorage.getItem('google_client_id');
    const savedSheetUrl = localStorage.getItem('google_sheet_url');
    if (savedClientId) setClientId(savedClientId);
    if (savedSheetUrl) setSheetUrl(savedSheetUrl);
  }, []);

  const saveConfig = () => {
    localStorage.setItem('google_client_id', clientId);
    localStorage.setItem('google_sheet_url', sheetUrl);
    setShowConfig(false);
  };

  const processEmailGeneration = useCallback(async (leadList: Company[]) => {
    let completed = 0;
    const total = leadList.length;
    setEmailGenProgress({ current: 0, total });

    for (const company of leadList) {
        if (company.emailDraft) {
            completed++;
            setEmailGenProgress({ current: completed, total });
            continue;
        }

        try {
            const draft = await generateEmailForCompany(company);

            // Update state immediately
            setCompanies(prevCompanies => 
                prevCompanies.map(c => 
                    c.companyName === company.companyName 
                        ? { ...c, emailDraft: draft } 
                        : c
                )
            );
        } catch (e) {
            console.warn(`Failed to auto-generate email for ${company.companyName}`, e);
        }

        completed++;
        setEmailGenProgress({ current: completed, total });
    }

    setEmailGenProgress(null);
  }, []);


  const fetchCompanies = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    setInfo(null);
    setSuccessMessage(null);
    setCompanies([]);
    setSelectedCompanyNames(new Set());
    setEmailGenProgress(null);

    try {
      // 1. Research Phase (Gemini)
      const data = await getSeriesALeads(icp);

      // 2. Verification Phase (Check Domains/MX/Parking)
      const verifiedLeads = await filterVerifiedLeads(data);

      const filteredCount = data.length - verifiedLeads.length;

      if (data.length > 0 && filteredCount > 0) {
          setInfo(`Market Research complete: Found ${data.length} potential leads. Verified ${verifiedLeads.length} valid companies (removed ${filteredCount} with invalid websites or emails).`);
      } else if (data.length > 0) {
          setInfo(`Market Research complete: Found and verified ${data.length} leads.`);
      }

      setCompanies(verifiedLeads);
      setSelectedCompanyNames(new Set(verifiedLeads.map(c => c.companyName)));

      // 3. Email Marketing Phase (Gemini)
      if (verifiedLeads.length > 0) {
          processEmailGeneration(verifiedLeads);
      }

    } catch (err) {
      if (err instanceof Error) {
        setError(err.message);
      } else {
        setError('An unknown error occurred.');
      }
    } finally {
      setIsLoading(false);
    }
  }, [icp, processEmailGeneration]);

  const handleToggleSelection = useCallback((companyName: string) => {
    setSelectedCompanyNames(prev => {
      const newSet = new Set(prev);
      if (newSet.has(companyName)) {
        newSet.delete(companyName);
      } else {
        newSet.add(companyName);
      }
      return newSet;
    });
  }, []);

  const handleBulkSelection = useCallback((companyNames: string[], shouldSelect: boolean) => {
    setSelectedCompanyNames(prev => {
      const newSet = new Set(prev);
      companyNames.forEach(name => {
        if (shouldSelect) {
          newSet.add(name);
        } else {
          newSet.delete(name);
        }
      });
      return newSet;
    });
  }, []);

  const handleExportToSheets = useCallback(async () => {
    const companiesToExport = companies.filter(c => selectedCompanyNames.has(c.companyName));

    if (companiesToExport.length === 0) {
        setInfo("No companies selected to export.");
        return;
    }

    if (!clientId) {
        setShowConfig(true);
        setInfo("Please configure your Google Client ID to enable Sheets export.");
        return;
    }

    setIsExporting(true);
    setError(null);
    setSuccessMessage(null);

    try {
        await exportToGoogleSheets(companiesToExport, sheetUrl, clientId);
        setSuccessMessage(`Successfully exported ${companiesToExport.length} leads to Google Sheets.`);
    } catch (err: any) {
        console.error("Sheets Export error:", err);
        if (err.result && err.result.error && err.result.error.message) {
             setError(`Export failed: ${err.result.error.message}`);
        } else {
             setError("Failed to export to Google Sheets. Check your permissions and Client ID.");
        }
    } finally {
        setIsExporting(false);
    }
  }, [companies, selectedCompanyNames, sheetUrl, clientId]);


  return (
    <>
    <div className="min-h-screen bg-gray-900 text-white font-sans flex flex-col items-center p-4 sm:p-6 md:p-8">
      <div className="w-full max-w-7xl mx-auto">
        <header className="text-center mb-8">
          <h1 className="text-4xl sm:text-5xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-blue-600">
            Creative Blue Lead Generator
          </h1>
          <p className="mt-2 text-lg text-gray-400">
            AI-Powered Market Research & Outreach Automation
          </p>
        </header>

        <main className="flex flex-col items-center">
          <div className="w-full max-w-2xl bg-gray-800/50 p-6 rounded-lg border border-gray-700 mb-8">
             <label htmlFor="icp" className="block text-sm font-medium text-gray-300 mb-2">
                Ideal Client Profile & Research Query
            </label>
            <textarea
                id="icp"
                value={icp}
                onChange={(e) => setIcp(e.target.value)}
                placeholder="e.g., B2B SaaS companies in the fintech space that recently raised Series A..."
                className="w-full h-24 p-3 bg-gray-900 border border-gray-600 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-colors text-gray-200 placeholder-gray-500"
            />
            <p className="mt-2 text-xs text-gray-500">Define the companies you want the AI Researcher to find.</p>
          </div>

          <div className="w-full flex flex-col sm:flex-row justify-center gap-4 mb-8">
            <button
              onClick={fetchCompanies}
              disabled={isLoading || (emailGenProgress !== null)}
              className="px-8 py-3 bg-blue-600 text-white font-bold rounded-lg shadow-lg hover:bg-blue-700 disabled:bg-blue-900 disabled:cursor-not-allowed disabled:text-gray-400 transition-all duration-300 ease-in-out transform hover:scale-105 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-opacity-50"
            >
              {isLoading ? 'Researching Market...' : (emailGenProgress ? `Drafting Emails (${emailGenProgress.current}/${emailGenProgress.total})...` : 'Start Research & Generate Leads')}
            </button>

            {companies.length > 0 && (
                <div className="flex gap-2">
                    <button
                        onClick={handleExportToSheets}
                        disabled={selectedCompanyNames.size === 0 || isExporting}
                        className="px-8 py-3 bg-green-600 text-white font-bold rounded-lg shadow-lg hover:bg-green-700 disabled:bg-green-900 disabled:cursor-not-allowed disabled:text-gray-400 transition-all duration-300 ease-in-out transform hover:scale-105 focus:outline-none focus:ring-2 focus:ring-green-500 focus:ring-opacity-50 flex items-center gap-2"
                    >
                        {isExporting ? (
                            <span>Exporting...</span>
                        ) : (
                            <>
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 24 24" fill="currentColor">
                                    <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-1 15h-2v-2h2v2zm0-4h-2V7h2v6z" fill="none"/>
                                    <path d="M19 3H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zM9 17H7v-7h2v7zm4 0h-2V7h2v10zm4 0h-2v-4h2v4z"/>
                                </svg>
                                {selectedCompanyNames.size > 0 
                                    ? `Export to Sheets (${selectedCompanyNames.size})` 
                                    : 'Export to Sheets'}
                            </>
                        )}
                    </button>
                    <button 
                        onClick={() => setShowConfig(!showConfig)}
                        className="p-3 bg-gray-700 text-white rounded-lg hover:bg-gray-600 transition-colors"
                        title="Configure Sheets Settings"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" />
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
