import React, { useState, useCallback, useEffect } from 'react';
import { Company, EmailContent } from './types';
import { getSeriesALeads, generateEmailForCompany } from './services/geminiService';
import { filterVerifiedLeads } from './services/verificationService';
import { exportToGoogleSheets } from './services/sheetsService';
import CompanyTable from './components/CompanyTable';
import LoadingSpinner from './components/LoadingSpinner';
import ErrorDisplay from './components/ErrorDisplay';
import InfoDisplay from './components/InfoDisplay';
import SuccessDisplay from './components/SuccessDisplay';
import EmailModal from './components/EmailModal';

// Constants
const DEFAULT_SHEET_URL = "https://docs.google.com/spreadsheets/d/1f4Y9M89GssWIxTbBUxP557_ruWnCG4PIV-f3Slo5CG0/edit?gid=516299967#gid=516299967";

const App: React.FC = () => {
  const [companies, setCompanies] = useState<Company[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [info, setInfo] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  const defaultIcp = "Startup companies in the United States that have either obtained or are seeking Series A round of funding.";
  const [icp, setIcp] = useState<string>(defaultIcp);

  // Selection state
  const [selectedCompanyNames, setSelectedCompanyNames] = useState<Set<string>>(new Set());

  // Email generation queue state
  const [emailGenProgress, setEmailGenProgress] = useState<{ current: number; total: number } | null>(null);

  // Sheets Config
  const [sheetUrl, setSheetUrl] = useState<string>(DEFAULT_SHEET_URL);
  const [clientId, setClientId] = useState<string>('');
  const [showConfig, setShowConfig] = useState<boolean>(false);
  const [isExporting, setIsExporting] = useState<boolean>(false);

  useEffect(() => {
    // Load persisted config
    const savedClientId = localStorage.getItem('google_client_id');
    const savedSheetUrl = localStorage.getItem('google_sheet_url');
    if (savedClientId) setClientId(savedClientId);
    if (savedSheetUrl) setSheetUrl(savedSheetUrl);
  }, []);

  const saveConfig = () => {
    localStorage.setItem('google_client_id', clientId);
    localStorage.setItem('google_sheet_url', sheetUrl);
    setShowConfig(false);
  };

  const processEmailGeneration = useCallback(async (leadList: Company[]) => {
    let completed = 0;
    const total = leadList.length;
    setEmailGenProgress({ current: 0, total });

    for (const company of leadList) {
        if (company.emailDraft) {
            completed++;
            setEmailGenProgress({ current: completed, total });
            continue;
        }

        try {
            const draft = await generateEmailForCompany(company);

            // Update state immediately
            setCompanies(prevCompanies => 
                prevCompanies.map(c => 
                    c.companyName === company.companyName 
                        ? { ...c, emailDraft: draft } 
                        : c
                )
            );
        } catch (e) {
            console.warn(`Failed to auto-generate email for ${company.companyName}`, e);
        }

        completed++;
        setEmailGenProgress({ current: completed, total });
    }

    setEmailGenProgress(null);
  }, []);


  const fetchCompanies = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    setInfo(null);
    setSuccessMessage(null);
    setCompanies([]);
    setSelectedCompanyNames(new Set());
    setEmailGenProgress(null);

    try {
      // 1. Research Phase (Gemini)
      const data = await getSeriesALeads(icp);

      // 2. Verification Phase (Check Domains/MX/Parking)
      const verifiedLeads = await filterVerifiedLeads(data);

      const filteredCount = data.length - verifiedLeads.length;

      if (data.length > 0 && filteredCount > 0) {
          setInfo(`Market Research complete: Found ${data.length} potential leads. Verified ${verifiedLeads.length} valid companies (removed ${filteredCount} with invalid websites or emails).`);
      } else if (data.length > 0) {
          setInfo(`Market Research complete: Found and verified ${data.length} leads.`);
      }

      setCompanies(verifiedLeads);
      setSelectedCompanyNames(new Set(verifiedLeads.map(c => c.companyName)));

      // 3. Email Marketing Phase (Gemini)
      if (verifiedLeads.length > 0) {
          processEmailGeneration(verifiedLeads);
      }

    } catch (err) {
      if (err instanceof Error) {
        setError(err.message);
      } else {
        setError('An unknown error occurred.');
      }
    } finally {
      setIsLoading(false);
    }
  }, [icp, processEmailGeneration]);

  const handleToggleSelection = useCallback((companyName: string) => {
    setSelectedCompanyNames(prev => {
      const newSet = new Set(prev);
      if (newSet.has(companyName)) {
        newSet.delete(companyName);
      } else {
        newSet.add(companyName);
      }
      return newSet;
    });
  }, []);

  const handleBulkSelection = useCallback((companyNames: string[], shouldSelect: boolean) => {
    setSelectedCompanyNames(prev => {
      const newSet = new Set(prev);
      companyNames.forEach(name => {
        if (shouldSelect) {
          newSet.add(name);
        } else {
          newSet.delete(name);
        }
      });
      return newSet;
    });
  }, []);

  const handleExportToSheets = useCallback(async () => {
    const companiesToExport = companies.filter(c => selectedCompanyNames.has(c.companyName));

    if (companiesToExport.length === 0) {
        setInfo("No companies selected to export.");
        return;
    }

    if (!clientId) {
        setShowConfig(true);
        setInfo("Please configure your Google Client ID to enable Sheets export.");
        return;
    }

    setIsExporting(true);
    setError(null);
    setSuccessMessage(null);

    try {
        await exportToGoogleSheets(companiesToExport, sheetUrl, clientId);
        setSuccessMessage(`Successfully exported ${companiesToExport.length} leads to Google Sheets.`);
    } catch (err: any) {
        console.error("Sheets Export error:", err);
