                              placeholder="e.g., 123456789-abc...apps.googleusercontent.com"
                              className="w-full p-2 bg-gray-900 border border-gray-600 rounded text-sm text-white"
                          />
                      </div>
                      <div className="mb-6">
                          <label className="block text-sm font-medium text-gray-400 mb-1">Target Spreadsheet URL</label>
                          <input 
                              type="text" 
                              value={sheetUrl}
                              onChange={(e) => setSheetUrl(e.target.value)}
                              className="w-full p-2 bg-gray-900 border border-gray-600 rounded text-sm text-white"
                          />
                      </div>
                      <div className="flex justify-end gap-2">
                          <button onClick={() => setShowConfig(false)} className="px-4 py-2 bg-gray-700 rounded hover:bg-gray-600">Cancel</button>
                          <button onClick={saveConfig} className="px-4 py-2 bg-blue-600 rounded hover:bg-blue-500">Save</button>
                      </div>
                  </div>
              </div>
          )}

          <div className="w-full">
            {isLoading && <LoadingSpinner />}
            {emailGenProgress && (
                <div className="mb-4 w-full bg-gray-800 rounded-full h-2.5 dark:bg-gray-700 overflow-hidden">
                    <div className="bg-blue-600 h-2.5 rounded-full transition-all duration-500" style={{ width: `${(emailGenProgress.current / emailGenProgress.total) * 100}%` }}></div>
                    <p className="text-center text-xs text-gray-400 mt-1">Automatically generating email drafts: {emailGenProgress.current} / {emailGenProgress.total}</p>
