            {!isLoading && !error && companies.length === 0 && (
                 <div className="text-center p-8 bg-gray-800/50 rounded-lg border border-gray-700">
                    <p className="text-gray-400">Refine your Ideal Client Profile above and click the button to start the AI research process.</p>
                </div>
            )}
          </div>
        </main>
      </div>
    </div>
    </>
  );
};

