import ErrorDisplay from './ErrorDisplay';

interface EmailModalProps {
  isOpen: boolean;
  onClose: () => void;
  company: Company | null;
  emailContent: EmailContent | null;
  isLoading: boolean;
  error: string | null;
}

const LOGO_URL = "https://drive.google.com/uc?id=1CSuuTHp65rEhbiYdNKr_Qtc7xOdJlAwE";

const EmailModal: React.FC<EmailModalProps> = ({ isOpen, onClose, company, emailContent, isLoading, error }) => {
  const [subjectCopied, setSubjectCopied] = useState(false);
  const [bodyCopied, setBodyCopied] = useState(false);

  if (!isOpen) return null;

  const handleCopy = (text: string, type: 'subject' | 'body') => {
    navigator.clipboard.writeText(text);
    if (type === 'subject') {
      setSubjectCopied(true);
      setTimeout(() => setSubjectCopied(false), 2000);
    } else {
      setBodyCopied(true);
      setTimeout(() => setBodyCopied(false), 2000);
    }
  };

  return (
    <div 
        className="fixed inset-0 bg-black bg-opacity-70 z-50 flex justify-center items-center p-4"
        onClick={onClose}
        aria-modal="true"
        role="dialog"
    >
      <div 
        className="bg-gray-800 rounded-lg shadow-2xl w-full max-w-2xl max-h-[90vh] flex flex-col border border-gray-700"
        onClick={(e) => e.stopPropagation()}
      >
        <header className="flex justify-between items-center p-4 border-b border-gray-700">
          <div className="flex items-center gap-3">
             <img 
                src={LOGO_URL} 
                alt="Creative Blue" 
                className="h-10 w-auto object-contain"
                style={{ display: 'block' }}
             />
             <h2 className="text-lg font-semibold text-white">Draft Email for {company?.companyName}</h2>
          </div>
          <button onClick={onClose} className="text-gray-400 hover:text-white text-2xl" aria-label="Close modal">&times;</button>
        </header>
        <div className="p-6 overflow-y-auto">
          {isLoading && <LoadingSpinner />}
          {error && <ErrorDisplay message={error} />}
          {emailContent && !isLoading && (
            <div className="space-y-4 text-gray-300">
              <div>
                <label className="text-xs font-semibold text-gray-400 uppercase">From</label>
                <p className="p-2 bg-gray-900 rounded-md border border-gray-700">minnie.ott@thinkcreativeblue.com</p>
              </div>
              <div>
                <label className="text-xs font-semibold text-gray-400 uppercase">To</label>
                <p className="p-2 bg-gray-900 rounded-md border border-gray-700">{company?.emailAddress || 'N/A'}</p>
              </div>
              <div>
                <label className="text-xs font-semibold text-gray-400 uppercase flex justify-between items-center">
                    <span>Subject</span>
                    <button 
                        onClick={() => handleCopy(emailContent.subject, 'subject')} 
                        className="text-xs px-2 py-1 bg-gray-700 hover:bg-gray-600 rounded-md transition-colors"
                    >
                        {subjectCopied ? 'Copied!' : 'Copy'}
                    </button>
                </label>
                <p className="p-2 bg-gray-900 rounded-md font-medium border border-gray-700">{emailContent.subject}</p>
              </div>
              <div>
                <label className="text-xs font-semibold text-gray-400 uppercase flex justify-between items-center">
                    <span>Body</span>
                    <button 
                        onClick={() => handleCopy(emailContent.body, 'body')}
                        className="text-xs px-2 py-1 bg-gray-700 hover:bg-gray-600 rounded-md transition-colors"
                    >
                        {bodyCopied ? 'Copied!' : 'Copy'}
                    </button>
                </label>
                <div className="p-3 bg-gray-900 rounded-md mt-1 text-sm leading-relaxed whitespace-pre-wrap border border-gray-700 h-64 overflow-y-auto custom-scrollbar">
                    {emailContent.body}
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

