        },
        founderName: {
          type: Type.STRING,
          description: "Name of the founder.",
        },
        founderEmail: {
          type: Type.STRING,
          description: "Email address of the founder.",
        },
      },
      required: ["companyName", "companyDescription", "websiteUrl", "linkedinUrl", "industry", "headquartersState", "contactTitle", "contactName", "emailAddress", "latestNews", "founderName", "founderEmail"],
    },
  };

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        temperature: 0.9, 
      },
    });

    const jsonText = response.text.trim();
    const companies: Company[] = JSON.parse(jsonText);
    return companies;

  } catch (error) {
    console.error("Error generating leads from Gemini API:", error);
    throw new Error("Failed to generate company leads. Please check the console for more details.");
  }
};


export const generateEmailForCompany = async (company: Company): Promise<EmailContent> => {
    if (!process.env.API_KEY) {
        throw new Error("API_KEY environment variable not set");
    }

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const prompt = `
        You are a professional and persuasive email marketer, skilled at crafting highly relevant and engaging lead magnet emails for "Creative Blue" (https://www.creativeblue.agency/).

        **Target Audience:**
        Name: ${company.contactName}
        Title: ${company.contactTitle}
        Company: ${company.companyName}
        Latest News: "${company.latestNews}"
        Location: ${company.headquartersState}

        **Task:**
        Draft a short, personalized email following these steps:
        1.  **Opening**: Warmly congratulate them on their specific Latest News ("${company.latestNews}"). Be genuine.
        2.  **Transition**: Seamlessly transition to how Creative Blue can support their momentum.
        3.  **Recommendation**: Recommend relevant services from https://www.creativeblue.agency/services-overview based on their industry (${company.industry}) and news.
        4.  **Tone**: Professional, persuasive, and concise. Avoid "salesy" jargon, all-caps, or excessive exclamation points. Do NOT use threatening language.
        5.  **Call to Action**: Include a clear, polite call to action directing them to https://www.creativeblue.agency/contact.

        **Output Format:**
        Return a JSON object with "subject" and "body". The body must use newline characters (\\n) for formatting.
    `;

    const responseSchema = {
        type: Type.OBJECT,
        properties: {
            subject: { type: Type.STRING },
            body: { type: Type.STRING }
        },
        required: ["subject", "body"],
    };

    try {
        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: responseSchema,
                temperature: 0.7,
            },
        });

        const jsonText = response.text.trim();
        const emailContent: EmailContent = JSON.parse(jsonText);
        return emailContent;

    } catch (error) {
        console.error("Error generating email from Gemini API:", error);
        throw new Error("Failed to draft email. Please try again.");
    }
};

import React, { useState, useCallback, useEffect } from 'react';
import { Company, EmailContent } from './types';
import { getSeriesALeads, generateEmailForCompany } from './services/geminiService';
import { filterVerifiedLeads } from './services/verificationService';
import { exportToGoogleSheets, fetchExistingCompanyNames } from './services/sheetsService';
import CompanyTable from './components/CompanyTable';
import LoadingSpinner from './components/LoadingSpinner';
import ErrorDisplay from './components/ErrorDisplay';
import InfoDisplay from './components/InfoDisplay';
import SuccessDisplay from './components/SuccessDisplay';
import EmailModal from './components/EmailModal';

// Constants
const DEFAULT_SHEET_URL = "https://docs.google.com/spreadsheets/d/1f4Y9M89GssWIxTbBUxP557_ruWnCG4PIV-f3Slo5CG0/edit?gid=516299967#gid=516299967";
// Using the direct content URL via Google's specialized delivery endpoint for Drive files
const LOGO_URL = "https://lh3.googleusercontent.com/d/1CSuuTHp65rEhbiYdNKr_Qtc7xOdJlAwE";

const App: React.FC = () => {
  const [companies, setCompanies] = useState<Company[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [info, setInfo] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  const defaultIcp = "Startup companies in the United States that have either obtained or are seeking Series A round of funding.";
  const [icp, setIcp] = useState<string>(defaultIcp);

  // Selection state
  const [selectedCompanyNames, setSelectedCompanyNames] = useState<Set<string>>(new Set());

  // Email generation queue state
  const [emailGenProgress, setEmailGenProgress] = useState<{ current: number; total: number } | null>(null);

  // Sheets Config
  const [sheetUrl, setSheetUrl] = useState<string>(DEFAULT_SHEET_URL);
  const [clientId, setClientId] = useState<string>('');
  const [showConfig, setShowConfig] = useState<boolean>(false);
  const [isExporting, setIsExporting] = useState<boolean>(false);

  useEffect(() => {
    // Load persisted config
    const savedClientId = localStorage.getItem('google_client_id');
    const savedSheetUrl = localStorage.getItem('google_sheet_url');
    if (savedClientId) setClientId(savedClientId);
    if (savedSheetUrl) setSheetUrl(savedSheetUrl);
  }, []);

  const saveConfig = () => {
    localStorage.setItem('google_client_id', clientId);
    localStorage.setItem('google_sheet_url', sheetUrl);
    setShowConfig(false);
  };

  const processEmailGeneration = useCallback(async (leadList: Company[]) => {
    let completed = 0;
    const total = leadList.length;
    setEmailGenProgress({ current: 0, total });

    for (const company of leadList) {
        if (company.emailDraft) {
            completed++;
            setEmailGenProgress({ current: completed, total });
            continue;
        }

        try {
            const draft = await generateEmailForCompany(company);

            // Update state immediately
            setCompanies(prevCompanies => 
                prevCompanies.map(c => 
                    c.companyName === company.companyName 
                        ? { ...c, emailDraft: draft } 
                        : c
                )
            );
        } catch (e) {
            console.warn(`Failed to auto-generate email for ${company.companyName}`, e);
        }

        completed++;
        setEmailGenProgress({ current: completed, total });
    }

    setEmailGenProgress(null);
  }, []);


  const fetchCompanies = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    setInfo(null);
    setSuccessMessage(null);
    setCompanies([]);
    setSelectedCompanyNames(new Set());
    setEmailGenProgress(null);

    try {
      // 1. Duplicate Prevention: Check existing companies in sheet
      let existingCompanies: string[] = [];
      if (clientId && sheetUrl) {
          setInfo("Checking spreadsheet for existing companies to prevent duplicates...");
          existingCompanies = await fetchExistingCompanyNames(sheetUrl, clientId);
          if (existingCompanies.length > 0) {
              console.log(`Found ${existingCompanies.length} existing companies to exclude.`);
          }
      }

      // 2. Research Phase (Gemini)
      setInfo("Researcher is analyzing the market...");
      const data = await getSeriesALeads(icp, existingCompanies);

      // 3. Post-generation duplicate filter (Double Check)
      const existingSet = new Set(existingCompanies.map(name => name.toLowerCase()));
      const uniqueData = data.filter(c => !existingSet.has(c.companyName.toLowerCase()));

      // 4. Verification Phase (Check Domains/MX/Parking)
      setInfo(`Verifying ${uniqueData.length} newly found leads...`);
      const verifiedLeads = await filterVerifiedLeads(uniqueData);

      const filteredCount = data.length - verifiedLeads.length;

      if (data.length > 0 && filteredCount > 0) {
          setInfo(`Market Research complete: Found ${data.length} potential leads. Verified ${verifiedLeads.length} valid companies (removed ${filteredCount} with invalid websites, emails, or duplicates).`);
      } else if (data.length > 0) {
          setInfo(`Market Research complete: Found and verified ${data.length} leads.`);
      }

      setCompanies(verifiedLeads);
      setSelectedCompanyNames(new Set(verifiedLeads.map(c => c.companyName)));

      // 5. Email Marketing Phase (Gemini)
      if (verifiedLeads.length > 0) {
          processEmailGeneration(verifiedLeads);
      } else {
          setInfo("No new unique leads found that match your criteria.");
      }

    } catch (err) {
      if (err instanceof Error) {
        if (err.message === 'AUTH_TIMEOUT') {
             setError('Duplicate check timed out. Please ensure you allow the Google login popup or configure your Client ID correctly.');
        } else {
             setError(err.message);
        }
      } else {
        setError('An unknown error occurred.');
      }
    } finally {
      setIsLoading(false);
    }
  }, [icp, clientId, sheetUrl, processEmailGeneration]);

  const handleToggleSelection = useCallback((companyName: string) => {
    setSelectedCompanyNames(prev => {
      const newSet = new Set(prev);
      if (newSet.has(companyName)) {
        newSet.delete(companyName);
      } else {
        newSet.add(companyName);
      }
      return newSet;
    });
  }, []);

  const handleBulkSelection = useCallback((companyNames: string[], shouldSelect: boolean) => {
    setSelectedCompanyNames(prev => {
      const newSet = new Set(prev);
      companyNames.forEach(name => {
        if (shouldSelect) {
          newSet.add(name);
        } else {
          newSet.delete(name);
        }
      });
      return newSet;
    });
  }, []);

  const handleExportToSheets = useCallback(async () => {
    const companiesToExport = companies.filter(c => selectedCompanyNames.has(c.companyName));

    if (companiesToExport.length === 0) {
        setInfo("No companies selected to export.");
        return;
    }

    if (!clientId) {
        setShowConfig(true);
        setInfo("Please configure your Google Client ID to enable Sheets export.");
        return;
    }

    setIsExporting(true);
    setError(null);
    setSuccessMessage(null);

    try {
        await exportToGoogleSheets(companiesToExport, sheetUrl, clientId);
        setSuccessMessage(`Successfully exported ${companiesToExport.length} leads to Google Sheets.`);
    } catch (err: any) {
        console.error("Sheets Export error:", err);
        if (err.result && err.result.error && err.result.error.message) {
             setError(`Export failed: ${err.result.error.message}`);
        } else if (err === 'AUTH_TIMEOUT') {
             setError("Authentication timed out. Did you close the popup?");
        } else {
             setError("Failed to export to Google Sheets. Check console for details.");
        }
    } finally {
        setIsExporting(false);
    }
  }, [companies, selectedCompanyNames, sheetUrl, clientId]);


  return (
    <>
    <div className="min-h-screen bg-gray-900 text-white font-sans flex flex-col items-center p-4 sm:p-6 md:p-8">
      <div className="w-full max-w-7xl mx-auto">
        <header className="flex flex-col items-center text-center mb-10">
          <div className="mb-6 h-24 sm:h-32 flex items-center justify-center">
            <img 
              src={LOGO_URL} 
              alt="Creative Blue Logo" 
              className="max-h-full w-auto object-contain"
              style={{ display: 'block' }}
              onError={(e) => {
                console.error("Logo failed to load");
                const img = e.target as HTMLImageElement;
                if (!img.dataset.retried) {
                    img.dataset.retried = 'true';
                    img.src = `${LOGO_URL}?t=${Date.now()}`;
                }
              }}
            />
          </div>
          <h1 className="text-4xl sm:text-5xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-blue-600">
            Lead Generator
          </h1>
          <p className="mt-2 text-lg text-gray-400">
            AI-Powered Market Research & Outreach Automation
          </p>
        </header>

        <main className="flex flex-col items-center">
          <div className="w-full max-w-2xl bg-gray-800/50 p-6 rounded-lg border border-gray-700 mb-8">
             <label htmlFor="icp" className="block text-sm font-medium text-gray-300 mb-2">
                Ideal Client Profile & Research Query
            </label>
            <textarea
                id="icp"
                value={icp}
                onChange={(e) => setIcp(e.target.value)}
                placeholder="e.g., B2B SaaS companies in the fintech space that recently raised Series A..."
                className="w-full h-24 p-3 bg-gray-900 border border-gray-600 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-colors text-gray-200 placeholder-gray-500"
            />
            <p className="mt-2 text-xs text-gray-500">Define the companies you want the AI Researcher to find.</p>
          </div>

          <div className="w-full flex flex-col sm:flex-row justify-center gap-4 mb-8">
            <button
              onClick={fetchCompanies}
              disabled={isLoading || (emailGenProgress !== null)}
              className="px-8 py-3 bg-blue-600 text-white font-bold rounded-lg shadow-lg hover:bg-blue-700 disabled:bg-blue-900 disabled:cursor-not-allowed disabled:text-gray-400 transition-all duration-300 ease-in-out transform hover:scale-105 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-opacity-50"
            >
              {isLoading ? 'Researching Market...' : (emailGenProgress ? `Drafting Emails (${emailGenProgress.current}/${emailGenProgress.total})...` : 'Start Research & Generate Leads')}
            </button>

            {companies.length > 0 && (
                <div className="flex gap-2">
                    <button
                        onClick={handleExportToSheets}
                        disabled={selectedCompanyNames.size === 0 || isExporting}
                        className="px-8 py-3 bg-green-600 text-white font-bold rounded-lg shadow-lg hover:bg-green-700 disabled:bg-green-900 disabled:cursor-not-allowed disabled:text-gray-400 transition-all duration-300 ease-in-out transform hover:scale-105 focus:outline-none focus:ring-2 focus:ring-green-500 focus:ring-opacity-50 flex items-center gap-2"
                    >
                        {isExporting ? (
                            <span>Exporting...</span>
                        ) : (
                            <>
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 24 24" fill="currentColor">
                                    <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-1 15h-2v-2h2v2zm0-4h-2V7h2v6z" fill="none"/>
                                    <path d="M19 3H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zM9 17H7v-7h2v7zm4 0h-2V7h2v10zm4 0h-2v-4h2v4z"/>
                                </svg>
                                {selectedCompanyNames.size > 0 
                                    ? `Export to Sheets (${selectedCompanyNames.size})` 
                                    : 'Export to Sheets'}
                            </>
                        )}
                    </button>
                    <button 
                        onClick={() => setShowConfig(!showConfig)}
                        className="p-3 bg-gray-700 text-white rounded-lg hover:bg-gray-600 transition-colors"
                        title="Configure Sheets Settings"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" />
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                        </svg>
                    </button>
                </div>
            )}
          </div>

          {/* Configuration Modal */}
          {showConfig && (
              <div className="fixed inset-0 bg-black bg-opacity-70 z-50 flex justify-center items-center p-4" onClick={() => setShowConfig(false)}>
                  <div className="bg-gray-800 rounded-lg shadow-xl border border-gray-700 p-6 w-full max-w-lg" onClick={(e) => e.stopPropagation()}>
                      <h3 className="text-xl font-bold mb-4">Google Sheets Configuration</h3>

                      <div className="mb-4 bg-yellow-900/30 border border-yellow-700 p-3 rounded text-sm text-yellow-200">
                         <p className="font-bold mb-1">Configuration Required for Duplicate Checking</p>
                         <p className="mb-2">To prevent adding companies that are already in your spreadsheet, please provide your Client ID and ensure your spreadsheet URL is correct.</p>
                      </div>

                      <div className="mb-4">
                          <label className="block text-sm font-medium text-gray-400 mb-1">Google Cloud Client ID</label>
                          <input 
                              type="text" 
                              value={clientId}
                              onChange={(e) => setClientId(e.target.value)}
                              placeholder="e.g., 123456789-abc...apps.googleusercontent.com"
                              className="w-full p-2 bg-gray-900 border border-gray-600 rounded text-sm text-white"
                          />
                      </div>
                      <div className="mb-6">
                          <label className="block text-sm font-medium text-gray-400 mb-1">Target Spreadsheet URL</label>
                          <input 
                              type="text" 
                              value={sheetUrl}
                              onChange={(e) => setSheetUrl(e.target.value)}
                              className="w-full p-2 bg-gray-900 border border-gray-600 rounded text-sm text-white"
                          />
                      </div>
                      <div className="flex justify-end gap-2">
                          <button onClick={() => setShowConfig(false)} className="px-4 py-2 bg-gray-700 rounded hover:bg-gray-600">Cancel</button>
                          <button onClick={saveConfig} className="px-4 py-2 bg-blue-600 rounded hover:bg-blue-500">Save</button>
                      </div>
                  </div>
              </div>
          )}

          <div className="w-full">
            {isLoading && <LoadingSpinner />}
            {emailGenProgress && (
                <div className="mb-4 w-full bg-gray-800 rounded-full h-2.5 dark:bg-gray-700 overflow-hidden">
                    <div className="bg-blue-600 h-2.5 rounded-full transition-all duration-500" style={{ width: `${(emailGenProgress.current / emailGenProgress.total) * 100}%` }}></div>
                    <p className="text-center text-xs text-gray-400 mt-1">Automatically generating email drafts: {emailGenProgress.current} / {emailGenProgress.total}</p>
                </div>
            )}
            {error && <ErrorDisplay message={error} />}
            {info && <InfoDisplay message={info} />}
            {successMessage && <SuccessDisplay message={successMessage} />}
            {companies.length > 0 && !isLoading && (
              <CompanyTable 
                companies={companies} 
                selectedCompanyNames={selectedCompanyNames}
                onToggleSelection={handleToggleSelection}
                onBulkSelection={handleBulkSelection}
              />
            )}
            {!isLoading && !error && companies.length === 0 && (
                 <div className="text-center p-8 bg-gray-800/50 rounded-lg border border-gray-700">
                    <p className="text-gray-400">Refine your Ideal Client Profile above and click the button to start the AI research process.</p>
                </div>
            )}
          </div>
        </main>
      </div>
    </div>
    </>
  );
};

export default App;
